// imaged by its DERIVATIVE. A knife edge at the focus blocks light deflected one way, so
// dn/dx maps to signed grey — the classic ghostly grey-on-grey density photograph. ----
const BW = 180, BH = Math.max(72, Math.round(BW * height / width));
const N = BW * BH;
