function fbm3(x, y, z) { return 0.57 * vn3(x, y, z) + 0.28 * vn3(x * 2.11 + 5.1, y * 2.11 - 3.2, z * 1.6 + 1.3) + 0.15 * vn3(x * 4.23 - 2.3, y * 4.23 + 7.7, z * 2.8 - 4.1); }

if (!S.init || S.seedUsed !== P.seed) {
