const tt = K.t;
const T = S.T, T2 = S.T2, PS = S.PS;
const sp = 0.3 + P.speed * 0.9;

// ---- velocity: curl of a drifting stream function + buoyancy. Sample psi to a grid once,
// difference the grid (4 fbm/cell for a per-cell FD costs 4x). ----
const zf = tt * 0.10 * sp + 2.3;
const dxo = 1.3 * Math.sin(tt * 0.053) + 0.6 * Math.sin(tt * 0.131 + 1.9);
const dyo = 1.1 * Math.cos(tt * 0.071) + 0.5 * Math.sin(tt * 0.167 + 0.6);
const fs = 2.6 / BH;
for (let j = 0; j < BH; j++) for (let i = 0; i < BW; i++) PS[j * BW + i] = fbm3(i * fs + dxo, j * fs + dyo, zf);

// ---- inject: pulsing thermal sources along the floor (the burner) ----
const nsrc = 2 + Math.round(P.density * 3);
const inj = (0.09 + P.density * 0.13) * (0.7 + K.swell * 0.35 + A.bass * 0.6);
for (let s = 0; s < nsrc; s++) {
  const bx = (0.14 + 0.72 * hsh(s * 7 + 1, 3, 2)) * BW
           + Math.sin(tt * (0.31 + hsh(s, 5, 2) * 0.4) + s * 2.1) * BW * 0.05;
  const by = BH - 2 - hsh(s * 3, 9, 2) * 3;
  const rad = (2.6 + hsh(s, 11, 2) * 3.4) * (0.7 + P.density * 0.7);
  const amp = inj * (0.55 + 0.45 * Math.sin(tt * (0.83 + s * 0.37) + s));
  const r2 = rad * rad;
  const i0 = Math.max(0, (bx - rad) | 0), i1 = Math.min(BW - 1, (bx + rad) | 0);
  const j0 = Math.max(0, (by - rad) | 0), j1 = Math.min(BH - 1, (by + rad) | 0);
  for (let j = j0; j <= j1; j++) for (let i = i0; i <= i1; i++) {
    const dx = i - bx, dy = j - by, d2 = dx * dx + dy * dy;
    if (d2 > r2) continue;
    const p = j * BW + i;
    T[p] = Math.min(1.6, T[p] + amp * (1 - d2 / r2));
  }
