// ---- semi-Lagrangian advection of the density field by (curl psi + buoyancy) ----
const buo = 5.5 + P.buoy * 22;
const adv = 0.85 * sp;
const wind = Math.sin(tt * 0.061) * 1.7 + Math.sin(tt * 0.149 + 1.1) * 0.8;
for (let j = 0; j < BH; j++) {
  const jm = (j > 0 ? j - 1 : 0) * BW, jp = (j < BH - 1 ? j + 1 : BH - 1) * BW, jc = j * BW;
  for (let i = 0; i < BW; i++) {
    const im = i > 0 ? i - 1 : 0, ip = i < BW - 1 ? i + 1 : BW - 1;
    let vx = (PS[jp + i] - PS[jm + i]) * 30 + wind;
    let vy = -(PS[jc + ip] - PS[jc + im]) * 30 - T[jc + i] * buo;   // hot fluid rises
    // backtrace
    let bx = i - vx * adv, by = j - vy * adv;
    bx = bx < 0 ? 0 : (bx > BW - 1.001 ? BW - 1.001 : bx);
    by = by < 0 ? 0 : (by > BH - 1.001 ? BH - 1.001 : by);
    const x0 = bx | 0, y0 = by | 0, fx = bx - x0, fy = by - y0;
    const x1 = x0 + 1 < BW ? x0 + 1 : x0, y1 = y0 + 1 < BH ? y0 + 1 : y0;
    const a = T[y0 * BW + x0], b = T[y0 * BW + x1], c = T[y1 * BW + x0], d = T[y1 * BW + x1];
    const v = (a + (b - a) * fx) + ((c + (d - c) * fx) - (a + (b - a) * fx)) * fy;
    T2[jc + i] = v * 0.9955;                      // slow dissipation
  }
}
// light diffusion + copy back
for (let j = 0; j < BH; j++) {
  const jm = (j > 0 ? j - 1 : 0) * BW, jp = (j < BH - 1 ? j + 1 : BH - 1) * BW, jc = j * BW;
  for (let i = 0; i < BW; i++) {
    const im = i > 0 ? i - 1 : 0, ip = i < BW - 1 ? i + 1 : BW - 1;
    T[jc + i] = T2[jc + i] * 0.88 + (T2[jc + im] + T2[jc + ip] + T2[jm + i] + T2[jp + i]) * 0.03;
  }
}

// ---- image the field by its derivative ----
const g = S.g; g.loadPixels(); const px = g.pixels;
const sec = K.section | 0;
const style = P.style;
const hb = ((P.hue + sec * 7 + Math.sin(tt * 0.023) * 12) % 360 + 360) % 360;
const gain = (14 + P.energy * 46) * (0.75 + A.rms * 0.5);
// the knife edge slowly rotates: which way the density gradient must lean to be cut
const ka = P.knife * 6.2831 + tt * 0.037;
const kx = Math.cos(ka), ky = Math.sin(ka);
