const tint1 = pal(0.0, 0.13, 0.0), tint2 = pal(0.5, 0.13, 0.0);
for (let j = 0; j < BH; j++) {
  const jm = (j > 0 ? j - 1 : 0) * BW, jp = (j < BH - 1 ? j + 1 : BH - 1) * BW, jc = j * BW;
  for (let i = 0; i < BW; i++) {
    const im = i > 0 ? i - 1 : 0, ip = i < BW - 1 ? i + 1 : BW - 1;
    const c = T[jc + i];
    const gx = (T[jc + ip] - T[jc + im]) * 0.5, gy = (T[jp + i] - T[jm + i]) * 0.5;
    let r, gg, b;
    if (style === 'rainbow') {              // rainbow schlieren: a colour filter replaces the knife
      const ang = Math.atan2(gy, gx) / 6.2831 + 0.5;
      const mag = Math.min(1, Math.sqrt(gx * gx + gy * gy) * gain * 0.55);
      const cc = pal(ang, 0.33, 0.0);
